const input = $input.first().json;
const required = ['country', 'source_table', 'comparison_table', 'data_date', 'diff'];
const missing = required.filter((key) => input[key] === undefined || input[key] === null || input[key] === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
const prompt = `You are a data-quality root-cause analyst. Analyze only the metadata below. Use source_sql and comparison_sql to identify the actual time predicates; begin/data_date is the start of the checked business-data interval, while an end timestamp may be the task cutoff and is not necessarily a midnight boundary. Identify the most likely start_date and end_date of the anomaly, explain evidence and confidence, and suggest one precise rerun date. If the evidence cannot establish a date boundary, use null and state the missing evidence. Do not execute SQL, do not invent table contents, do not call any external system. Return JSON only with keys: start_date, end_date, recommended_rerun_date, confidence, reasoning, evidence_needed.\n\nMetadata:\n${JSON.stringify(input)}`;
return [{ json: { input, prompt } }];

const raw = $json.choices?.[0]?.message?.content ?? $json.output_text ?? $json.text ?? JSON.stringify($json);
let analysis;
try { analysis = typeof raw === 'string' ? JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '')) : raw; } catch { analysis = { reasoning: String(raw), confidence: 'unknown', evidence_needed: ['AI response was not valid JSON'] }; }
const iso = /^\d{4}-\d{2}-\d{2}$/;
for (const key of ['start_date', 'end_date', 'recommended_rerun_date']) { if (analysis[key] && !iso.test(String(analysis[key]))) analysis[key] = null; }
return [{ json: { status: 'complete', analysis } }];
